import React, { Suspense } from 'react';
import PlayerPanel from "./UI/PlayerPanel/PlayerPanel";

const Exchange = React.lazy(() => import("../pages/Exchange"));
const Mine = React.lazy(() => import("../pages/Mine"));
const SuperGame = React.lazy(() => import("../pages/SuperGame"));
const Friends = React.lazy(() => import("../pages/Friends"));
const Earn = React.lazy(() => import("../pages/Earn"));
const Clans = React.lazy(() => import("../pages/Clans"));

function returnPage(page, player, setPlayer, setBoost, setMinePanel, url) {
    if (page === "home"||page === "/"||page === "exchange") {
        return (
            <Exchange
                player={player}
                setPlayer={setPlayer}
                money={player.money}
                energy={player.energy}
                setBoost={setBoost}
                url={url}
            />
        );
    } else if (page === "game") {
        return (
            <SuperGame
                money={player.money}
                energy={player.energy}
                setBoost={setBoost}
                timer={"03:25:30"}
                setMinePanel={setMinePanel}
                url={url}
            />
        );
    } else if (page === "friends") {
        return <Friends url={url}/>;
    } else if (page === "earn") {
        return <Earn url={url}/>;
    } else if (page === "clans") {
        return <Clans url={url}/>;
    }
}

const Layers = ({
    avatar,
    player,
    setPlayer,
    page,
    playerPanel,
    setSettings,
    setBoost,
    setProgress,
    setMinePanel,
    url
}) => {
    return (
        <div style={{ position: "relative" }}>
            {playerPanel && (
                <PlayerPanel
                    avatar={avatar}
                    setProgress={setProgress}
                    key={player.id}
                    setSettings={setSettings}
                    player={player}
                />
            )}
                {returnPage(page, player, setPlayer, setBoost, setMinePanel, url)}
        </div>
    );
};

export default Layers;
