// Функция для получения данных из localStorage
const getInitDataFromStorage = () => {
    try {
        const storedData = localStorage.getItem('initData');
        return storedData ? storedData : null;
    } catch (error) {
        console.error('Ошибка при получении данных из localStorage:', error);
        return null;
    }
};

// Функция для сохранения данных в localStorage
const saveInitDataToStorage = (data) => {
    try {
        if (data) {
            localStorage.setItem('initData', data);
        }
    } catch (error) {
        console.error('Ошибка при сохранении данных в localStorage:', error);
    }
};

export function useTelegram() {
    const getTg = () => window.Telegram?.WebApp || null;
    const tg = getTg();

    // Получаем initData из Telegram или localStorage
    const initData = tg?.initData || getInitDataFromStorage();
    
    // Сохраняем initData в localStorage
    saveInitDataToStorage(initData);

    const onClose = () => {
        const telegram = getTg();
        telegram?.close();
    };

    const onToggleButton = () => {
        const telegram = getTg();
        if (telegram?.MainButton?.isVisible) {
            telegram.MainButton.hide();
        } else {
            telegram.MainButton.show();
        }
    };

    const expand = () => {
        const telegram = getTg();
        if (telegram?.expand) {
            telegram.expand();
        }
    };

    const ready = () => {
        const telegram = getTg();
        if (telegram?.ready) {
            telegram.ready();
        }
    };

    const shareMessage = (message) => {
        const telegram = getTg();
        if (!message || typeof message !== 'string' || !telegram) {
            console.error('Invalid message or Telegram WebApp not available');
            return;
        }

        telegram.openLink(`https://t.me/share/url?url=${encodeURIComponent(message)}`)
            .catch((error) => console.error('Error sharing message:', error));
    };
    
    return {
        onClose,
        onToggleButton,
        tg,
        ready,
        initData,
        user: tg?.initDataUnsafe?.user || null,
        queryId: tg?.initDataUnsafe?.query_id || null,
        photoUrl: tg?.initDataUnsafe?.user?.photo_url || null,
        expand,
        shareMessage,
        language: tg?.initDataUnsafe?.user?.language_code || 'en',
    }
}