import React, { useEffect, useState, useRef } from 'react';
import './styles/App.css';
import { usePlayerStore } from "./store/playerStore.mjs";
import { useTelegram } from "./components/hooks/useTelegram";
import { useTranslation } from "./hooks/useTranslation";
import { BrowserRouter, Route, Routes } from "react-router-dom";
import Loading from "./pages/Loading";
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import Settings from "./components/UI/Settings/Settings";
import Boost from "./components/UI/Boost/Boost";
import Progress from "./components/UI/Progress/Progress";
import MinePanel from "./components/UI/MinePanel/MinePanel";
import telegramAnalytics from '@telegram-apps/analytics';
import { urlBase } from './url';
import { login } from './http/auth.js';

// Lazy imports
// const Navbar = React.lazy(() => import("./components/UI/Navbar/Navbar"));
// const Layers = React.lazy(() => import("./components/Layers"));

import Navbar from './components/UI/Navbar/Navbar';
import Layers from './components/Layers';

function App() {
    const { user, tg, initData, photoUrl, expand } = useTelegram();
    const { player, updatePlayer } = usePlayerStore();

    const [settings, setSettings] = useState(false);
    const [isError, setIsError] = useState(false);
    const [boost, setBoost] = useState(false);
    const [progress, setProgress] = useState(false);
    const [minePanel, setMinePanel] = useState(false);
    
    // Два отдельных состояния для загрузки
    const [isLoadingData, setIsLoadingData] = useState(true); 
    const [showLoadingScreen, setShowLoadingScreen] = useState(true); 
    const [isPageReady, setIsPageReady] = useState(false); 

    const telegramLanguage = initData?.user?.language_code;
    const language = localStorage.getItem('language') || telegramLanguage;
    const { t } = useTranslation(language);
    localStorage.setItem('language', language);

    useEffect(() => {
        tg.ready();
        expand();
    }, []);

    // Таймер для задержки скрытия экрана загрузки
    const loadingTimerRef = useRef(null);

    const fetchPlayerData = async () => {
        setIsLoadingData(true);
        setIsError(false);
        
        try {
            console.log('Fetching player data...');
            const data = await login(initData); 
            
            if (data.token) {
                localStorage.setItem('token', data.token);
            } else {
                console.warn('Token is missing in response');
            }
        
            const playerData = {
                id: data.id || 1,
                name: data.name || user?.username || 'Guest',
                role: data.role || 'CEO',
                money: data.money || 0,
                totalMoney: data.totalMoney || 0,
                profit: data.profit || 0,
                energy: data.energy || 0,
                rank: data.rank || 0,
                benefit: data.benefit || 0,
                key: data.key || 0,
                daily: data.combo_daily_tasks || [],
                reward: data.reward || null,
                wallet: data.wallet || null,
                boost: data?.boost || null
            };
        
            console.log('Player data loaded successfully');
            updatePlayer(playerData);
            
            setIsLoadingData(false);
            setIsError(false);
            
            loadingTimerRef.current = setTimeout(() => {
                setShowLoadingScreen(false);
                setIsPageReady(true);
                
                toast.info(t('App.toasts.welcome'), {
                    position: 'top-right',
                    autoClose: 3000,
                    theme: 'dark',
                });
                
                if (tg?.HapticFeedback?.impactOccurred) {
                    tg.HapticFeedback.impactOccurred('medium'); 
                }
            }, 2500); 
            
        } catch (error) {
            console.error('Error during fetchPlayerData:', error);
            toast.error(`Error: ${error.message}`, {
                position: 'top-right',
                autoClose: 5000,
                theme: 'dark',
            });
            setIsLoadingData(false);
            setIsError(true);
            
            // В случае ошибки сразу скрываем экран загрузки
            setShowLoadingScreen(false);
            setIsPageReady(true);
        }
    };

    useEffect(() => {
        // Очистка таймера при размонтировании
        return () => {
            if (loadingTimerRef.current) {
                clearTimeout(loadingTimerRef.current);
            }
        };
    }, []);

    useEffect(() => {
        const initializeApp = async () => {
            try {
                // Инициализация Telegram
                tg.ready();
                expand();
                
                // Загружаем данные пользователя
                await fetchPlayerData();
                
            } catch (e) {
                console.error('App initialization error:', e);
                toast.error(e.message || 'Initialization failed', {
                    position: 'top-right',
                    autoClose: 5000,
                    theme: 'dark',
                });
                setIsLoadingData(false);
                setIsError(true);
                setShowLoadingScreen(false);
                setIsPageReady(true);
            }
        };
        
        initializeApp();
    }, []);

    return (
        <div className="App">
            <ToastContainer />
            
            {showLoadingScreen && (
                <Loading />
            )}
            
            {isPageReady && (
                <>
                    {isError ? (
                        <div style={{
                            display: 'flex',
                            justifyContent: 'center',
                            alignItems: 'center',
                            height: '100vh',
                            backgroundColor: '#000',
                            color: '#fff',
                            flexDirection: 'column',
                            padding: '20px',
                            textAlign: 'center'
                        }}>
                            <h2>{t('App.errors.connectionError') || 'Ошибка соединения'}</h2>
                            <p>{t('App.errors.tryAgainLater') || 'Попробуйте позже'}</p>
                            <button 
                                onClick={() => {
                                    setShowLoadingScreen(true);
                                    setIsPageReady(false);
                                    fetchPlayerData();
                                }}
                                style={{
                                    marginTop: '20px',
                                    padding: '10px 20px',
                                    backgroundColor: '#007bff',
                                    color: '#fff',
                                    border: 'none',
                                    borderRadius: '5px',
                                    cursor: 'pointer'
                                }}
                            >
                                {t('App.buttons.retry') || 'Повторить'}
                            </button>
                        </div>
                    ) : (
                        <>
                            <Settings visible={settings} setVisible={setSettings}/>
                            <Boost visible={boost} setVisible={setBoost} money={player?.money || 0}/>
                            <Progress visible={progress} setVisible={setProgress} player={player} url={urlBase}/>
                            <MinePanel minePanel={minePanel} setMinePanel={setMinePanel} money={player?.money || 0} url={urlBase}/>
                            
                            <BrowserRouter>
                                <React.Suspense fallback={<Loading />}>
                                    <Routes>
                                        <Route
                                            path="home"
                                            element={
                                                <Layers
                                                    player={player}
                                                    setPlayer={updatePlayer}
                                                    page="home"
                                                    playerPanel={true}
                                                    setSettings={setSettings}
                                                    setBoost={setBoost}
                                                    setProgress={setProgress}
                                                    url={urlBase}
                                                />
                                            }
                                        />
                                        <Route
                                            path="game"
                                            element={
                                                // <Layers
                                                //     player={player}
                                                //     setPlayer={updatePlayer}
                                                //     page="farm"
                                                //     playerPanel={true}
                                                //     setSettings={setSettings}
                                                //     setBoost={setBoost}
                                                //     setProgress={setProgress}
                                                //     setMinePanel={setMinePanel}
                                                //     url={urlBase}
                                                // />
                                                <Layers
                                                    player={player}
                                                    setPlayer={updatePlayer}
                                                    page="game"
                                                    playerPanel={false}
                                                    setSettings={setSettings}
                                                    setBoost={setBoost}
                                                    setProgress={setProgress}
                                                    url={urlBase}
                                                />
                                            }
                                        />
                                        <Route
                                            path="friends"
                                            element={
                                                <Layers
                                                    player={player}
                                                    setPlayer={updatePlayer}
                                                    page="friends"
                                                    playerPanel={false}
                                                    setSettings={setSettings}
                                                    setBoost={setBoost}
                                                    setProgress={setProgress}
                                                    url={urlBase}
                                                />
                                            }
                                        />
                                        <Route
                                            path="earn"
                                            element={
                                                <Layers
                                                    player={player}
                                                    setPlayer={updatePlayer}
                                                    page="earn"
                                                    playerPanel={false}
                                                    setSettings={setSettings}
                                                    setBoost={setBoost}
                                                    setProgress={setProgress}
                                                    url={urlBase}
                                                />
                                            }
                                        />
                                        <Route
                                            path="clans"
                                            element={
                                                <Layers
                                                    player={player}
                                                    setPlayer={updatePlayer}
                                                    page="clans"
                                                    playerPanel={false}
                                                    setSettings={setSettings}
                                                    setBoost={setBoost}
                                                    setProgress={setProgress}
                                                    url={urlBase}
                                                />
                                            }
                                        />
                                        <Route
                                            path="*"
                                            element={
                                                <Layers
                                                    avatar={photoUrl || null}
                                                    player={player}
                                                    setPlayer={updatePlayer}
                                                    page="exchange"
                                                    playerPanel={true}
                                                    setSettings={setSettings}
                                                    setBoost={setBoost}
                                                    setProgress={setProgress}
                                                    url={urlBase}
                                                />
                                            }
                                        />
                                    </Routes>
                                    <Navbar />
                                </React.Suspense>
                            </BrowserRouter>
                        </>
                    )}
                </>
            )}
        </div>
    );
}

export default App;