import { create } from 'zustand';

export const usePlayerStore = create((set, get) => ({
    player: null,
    superGame: {
        selectedCategory: null,
        currentGame: null,
        prizes: [],
        wonPrizes: [],
        totalClicks: 0,
        currentPoints: 0,
        targetPoints: 1000,
    },
    
    updatePlayer: (updates) => {
        set((state) => ({
            player: { ...state.player, ...updates }
        }));
    },
    
    updateEnergy: (energy) => {
        set((state) => ({
            player: { ...state.player, energy }
        }));
    },
    
    updateMoney: (money) => {
        set((state) => ({
            player: { ...state.player, money }
        }));
    },
    
    // SuperGame methods
    setSuperGameCategory: (category) => {
        set((state) => ({
            superGame: { ...state.superGame, selectedCategory: category }
        }));
    },
    
    startSuperGame: (gameId) => {
        set((state) => ({
            superGame: { 
                ...state.superGame, 
                currentGame: gameId,
                currentPoints: 0,
                totalClicks: 0
            }
        }));
    },
    
    updateSuperGamePoints: (points) => {
        set((state) => {
            const newPoints = state.superGame.currentPoints + points;
            const newTotalClicks = state.superGame.totalClicks + 1;
            
            // Check if prize won
            const wonPrizes = [...state.superGame.wonPrizes];
            const availablePrizes = state.superGame.prizes.filter(
                prize => !wonPrizes.some(wp => wp.id === prize.id)
            );
            
            let newWonPrizes = [...wonPrizes];
            if (availablePrizes.length > 0 && newPoints >= state.superGame.targetPoints) {
                // Award random prize
                const randomPrize = availablePrizes[Math.floor(Math.random() * availablePrizes.length)];
                newWonPrizes.push(randomPrize);
                
                // Reset points for next prize
                return {
                    superGame: {
                        ...state.superGame,
                        currentPoints: 0,
                        totalClicks: newTotalClicks,
                        wonPrizes: newWonPrizes
                    }
                };
            }
            
            return {
                superGame: {
                    ...state.superGame,
                    currentPoints: newPoints,
                    totalClicks: newTotalClicks
                }
            };
        });
    },
    
    addSuperGamePrize: (prize) => {
        set((state) => ({
            superGame: {
                ...state.superGame,
                prizes: [...state.superGame.prizes, prize]
            }
        }));
    },
    
    resetSuperGame: () => {
        set((state) => ({
            superGame: {
                ...state.superGame,
                currentGame: null,
                currentPoints: 0,
                totalClicks: 0
            }
        }));
    }
}));