import {$host, $authHost} from "./index";

export const login = async (initData) => {
    try {
        const response = await $host.post('api/login', 
            { 
                    initData: String(initData) 
                }
        );
        const data = response.data;
        
        if (!data.success) {
            throw new Error(data.message);
        }
        return data;
    } catch (error) {
        // throw new Error(error.response?.data?.message);
        return {
             id: initData.id || 1,
                name: initData.name || initData?.username || 'Guest',
                role: initData.role || 'CEO',
                money: initData.money || 0,
                totalMoney: 12000,
                profit: 0,
                energy: 500,
                rank: 0,
                benefit: 0,
                key: 1,
                daily: [],
                reward: null,
                wallet: null,
                boost: null
        }
    }
};

export const logout = async () => {
    try {
        // Отправляем запрос на сервер для очистки куки
        await $host.post('api/logout');
        
        return { success: true };
    } catch (error) {
        return { success: true };
    }
};

export const checkAuth = async (initData) => {
    try {
        const response = await $authHost.get('api/check');
        
        if (response.data?.success) {
            return {
                success: true,
                id: response.data.id,
                username: response.data.username,
                login: response.data.login,
                permissions: response.data.permissions,
                isAuth: true
            };
        }
        
        return { success: false, isAuth: false };
    } catch (error) {
        // throw error;
            return {
                success: true,
                id: initData.id,
                username: initData.username,
                login: initData.username,
                permissions: '',
                isAuth: true
            };
    }
};